// Two pdfmake families cover the identity's four weights: the base family
// pairs Regular 400 with SemiBold 600 (body text and headings — the
// system's main axis), the second pairs Medium 500 with Bold 700 (labels
// and the rare small-print emphasis). Italic exists for quotations only.
export const identityFonts = {
  IBMPlexSans: {
    normal: 'IBMPlexSans-Regular.ttf',
    bold: 'IBMPlexSans-SemiBold.ttf',
    italics: 'IBMPlexSans-Italic.ttf',
    bolditalics: 'IBMPlexSans-Italic.ttf',
  },
  IBMPlexSansMedium: {
    normal: 'IBMPlexSans-Medium.ttf',
    bold: 'IBMPlexSans-Bold.ttf',
    italics: 'IBMPlexSans-Medium.ttf',
    bolditalics: 'IBMPlexSans-Bold.ttf',
  },
};
